  j constant jsonb := $j$[
{"id":"1a718e60-07ab-486e-9eff-0f386130ec7f","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"es","slug":"bulgogi-carne-marinada-coreana","public_path":"/bulgogi-carne-marinada-coreana","source_url":null,"title":"Bulgogi, carne marinada coreana","excerpt":"Bulgogi casero: láminas finas de carne de res marinadas con salsa de soja, pera, ajo y sésamo, y salteadas con cebolla. Se sirve con arroz y lechuga. Rinde 4 porciones.","summary":"Este bulgogi lleva láminas finas de carne de res marinadas en salsa de soja, pera rallada, ajo, jengibre, azúcar moreno y aceite de sésamo. Se saltean a fuego fuerte con cebolla y cebolleta hasta que quedan doradas y brillantes, y se sirven con arroz blanco y hojas de lechuga.\n\nLlevan 80 minutos de preparación, 60 de ellos de marinado, y 15 de cocción. Rinde 4 porciones.","category":"Platos principales","difficulty":"Fácil","course":"Plato principal","cuisine":"Coreana","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["bulgogi","receta de bulgogi","bulgogi carne marinada coreana","cómo hacer bulgogi","bulgogi de res","carne coreana marinada","bulgogi con arroz y lechuga"],"ingredients":[{"name":"carne de res (lomo o solomillo) en láminas finas","amount":"600","unit":"g","group":"Para la carne y la marinada"},{"name":"salsa de soja","amount":"4","unit":"cucharada","group":"Para la carne y la marinada"},{"name":"pera","amount":"1/2","unit":"","group":"Para la carne y la marinada"},{"name":"dientes de ajo","amount":"4","unit":"","group":"Para la carne y la marinada"},{"name":"jengibre fresco rallado","amount":"1","unit":"cucharadita","group":"Para la carne y la marinada"},{"name":"azúcar moreno","amount":"2","unit":"cucharada","group":"Para la carne y la marinada"},{"name":"aceite de sésamo","amount":"1","unit":"cucharada","group":"Para la carne y la marinada"},{"name":"semillas de sésamo","amount":"1","unit":"cucharada","group":"Para la carne y la marinada"},{"name":"cebolla","amount":"1","unit":"","group":"Para saltear"},{"name":"cebolletas","amount":"3","unit":"","group":"Para saltear"},{"name":"aceite vegetal","amount":"1","unit":"cucharada","group":"Para saltear"},{"name":"arroz blanco cocido","amount":"600","unit":"g","group":"Para servir"},{"name":"hojas de lechuga","amount":"8","unit":"","group":"Para servir"}],"steps":[{"title":"Prepara los ingredientes","content":"Ten a mano 600 g de carne de res (lomo o solomillo), 4 cucharadas de salsa de soja, ½ pera, 4 dientes de ajo, jengibre, 2 cucharadas de azúcar moreno, aceite de sésamo, semillas de sésamo, 1 cebolla, 3 cebolletas, aceite vegetal, arroz cocido y lechuga.","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"Bulgogi, carne marinada coreana: Prepara los ingredientes"},{"title":"Corta la carne","content":"Congela la carne 30 minutos para cortarla con más facilidad. Con un cuchillo bien afilado, córtala en láminas de 2 a 3 mm, en sentido contrario a la fibra.","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"Bulgogi, carne marinada coreana: Corta la carne"},{"title":"Prepara la marinada","content":"En un bol mezcla 4 cucharadas de salsa de soja, ½ pera rallada, 4 dientes de ajo picados, 1 cucharadita de jengibre rallado, 2 cucharadas de azúcar moreno, 1 cucharada de aceite de sésamo y 1 cucharada de semillas de sésamo.","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"Bulgogi, carne marinada coreana: Prepara la marinada"},{"title":"Mezcla la carne con la marinada","content":"Añade las láminas de carne al bol y mezcla con las manos hasta que todas queden bien cubiertas.","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"Bulgogi, carne marinada coreana: Mezcla la carne con la marinada"},{"title":"Deja marinar","content":"Cubre el bol con film transparente y déjalo en la nevera de 1 a 4 horas. No lo dejes más tiempo: la pera ablanda demasiado la carne.","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"Bulgogi, carne marinada coreana: Deja marinar"},{"title":"Saltea la cebolla","content":"Calienta 1 cucharada de aceite en una sartén ancha a fuego fuerte. Añade 1 cebolla cortada en plumas y la parte blanca de 3 cebolletas en trozos y saltea 2 minutos, hasta que empiecen a dorarse.","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"Bulgogi, carne marinada coreana: Saltea la cebolla"},{"title":"Cocina la carne","content":"Añade la carne con su marinada en dos tandas, sin amontonarla, y saltea a fuego fuerte 5 o 6 minutos en total, hasta que esté dorada y la salsa quede brillante.","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"Bulgogi, carne marinada coreana: Cocina la carne"},{"title":"Sirve","content":"Sirve el bulgogi sobre 600 g de arroz blanco cocido, con hojas de lechuga para envolver la carne. Esparce por encima la parte verde de las cebolletas en rodajas.","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"Bulgogi, carne marinada coreana: Sirve"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"Bulgogi, carne marinada coreana"}],"notes":"Corta la carne lo más fina posible: así se marina rápido y se cocina en minutos. Cocínala en tandas y a fuego fuerte para que se dore en lugar de hervir en su jugo. En la mesa, se suele envolver un poco de carne y arroz en una hoja de lechuga. La pera aporta dulzor y ablanda la carne; si no tienes, usa una manzana. El plato es salado por la salsa de soja: no añadas sal. Se conserva 3 días en la nevera y se puede congelar hasta 2 meses.","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1 porción (unos 330 g con arroz y lechuga)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones: 600 g de carne de res magra (valor orientativo, sin FDC id), 70 g de salsa de soja, 100 g de pera, 12 g de ajo, 2 g de jengibre, 28 g de azúcar moreno, 14 g de aceite de sésamo, 9 g de semillas de sésamo, 150 g de cebolla, 45 g de cebolleta (valor orientativo, sin FDC id), 14 g de aceite, 600 g de arroz blanco cocido y 80 g de lechuga (valor orientativo, sin FDC id), todo contado.","note":"Estimación por porción, incluido el arroz y la lechuga. El sodio es alto por la salsa de soja; con salsa de soja baja en sodio puede reducirse mucho. La marinada se cuenta completa, aunque parte quede en el bol.","inputs":[{"fdc_id":null,"description":"Carne de res magra tipo lomo o solomillo, cruda (proxy orientativo; 600 g)","grams":600,"per100":{"calories":180,"protein_g":20.5,"carbs_g":0,"fat_g":10.3,"saturated_fat_g":4.2,"fiber_g":0,"sodium_mg":55}},{"fdc_id":"174278","description":"Soy sauce made from soy and wheat (shoyu) (4 cucharadas ≈ 70 g)","grams":70,"per100":{"calories":53,"protein_g":8.14,"carbs_g":4.93,"fat_g":0.57,"saturated_fat_g":0.079,"fiber_g":0.8,"sodium_mg":5493}},{"fdc_id":"169118","description":"Pears, raw (½ pera ≈ 100 g)","grams":100,"per100":{"calories":57,"protein_g":0.36,"carbs_g":15.23,"fat_g":0.14,"saturated_fat_g":0.022,"fiber_g":3.1,"sodium_mg":1}},{"fdc_id":"169230","description":"Garlic, raw (4 dientes ≈ 12 g)","grams":12,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"169231","description":"Ginger root, raw (1 cucharadita rallado ≈ 2 g)","grams":2,"per100":{"calories":80,"protein_g":1.82,"carbs_g":17.77,"fat_g":0.75,"saturated_fat_g":0.2,"fiber_g":2.0,"sodium_mg":13}},{"fdc_id":"168833","description":"Sugars, brown (2 cucharadas ≈ 28 g)","grams":28,"per100":{"calories":380,"protein_g":0.12,"carbs_g":98.09,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":28}},{"fdc_id":"171016","description":"Oil, sesame, salad or cooking (1 cucharada ≈ 14 g)","grams":14,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":14.2,"fiber_g":0,"sodium_mg":0}},{"fdc_id":"170150","description":"Seeds, sesame seeds, whole, dried (1 cucharada ≈ 9 g)","grams":9,"per100":{"calories":573,"protein_g":17.73,"carbs_g":23.45,"fat_g":49.67,"saturated_fat_g":6.957,"fiber_g":11.8,"sodium_mg":11}},{"fdc_id":"170000","description":"Onions, raw (1 cebolla mediana ≈ 150 g)","grams":150,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":null,"description":"Cebolletas, crudas (proxy orientativo; 3 cebolletas ≈ 45 g)","grams":45,"per100":{"calories":32,"protein_g":1.83,"carbs_g":7.34,"fat_g":0.19,"saturated_fat_g":0.032,"fiber_g":2.6,"sodium_mg":16}},{"fdc_id":"172336","description":"Oil, canola (1 cucharada ≈ 14 g)","grams":14,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.365,"fiber_g":0,"sodium_mg":0}},{"fdc_id":"168878","description":"Rice, white, long-grain, regular, enriched, cooked (600 g)","grams":600,"per100":{"calories":130,"protein_g":2.69,"carbs_g":28.17,"fat_g":0.28,"saturated_fat_g":0.077,"fiber_g":0.4,"sodium_mg":1}},{"fdc_id":null,"description":"Hojas de lechuga, crudas (proxy orientativo; 8 hojas ≈ 80 g)","grams":80,"per100":{"calories":15,"protein_g":1.36,"carbs_g":2.87,"fat_g":0.15,"saturated_fat_g":0.02,"fiber_g":1.3,"sodium_mg":28}}]},"seo":{"title":"Bulgogi, carne marinada coreana con arroz y lechuga | Manual de Cocina","description":"Bulgogi casero: carne de res en láminas finas marinada con soja, pera, ajo y sésamo, y salteada con cebolla. Con arroz y lechuga, 4 porciones. Paso a paso.","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"¿Qué corte de carne se usa para el bulgogi?","a":"Lomo o solomillo de res cortado en láminas muy finas. También sirven la falda o el cuadril, siempre cortados en contra de la fibra."},{"q":"¿Cuánto tiempo hay que marinar el bulgogi?","a":"Entre 1 y 4 horas en la nevera. Menos tiempo da menos sabor, y más de 4 horas ablanda demasiado la carne por la pera."},{"q":"¿Con qué se sirve el bulgogi?","a":"Con arroz blanco y hojas de lechuga para envolver la carne. También va bien con kimchi o pepino en rodajas."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"a138fe32-49e6-50cf-8532-fae7a907f4b7","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"de","slug":"bulgogi-koreanisches-rindfleisch","public_path":"/de/bulgogi-koreanisches-rindfleisch","source_url":null,"title":"Bulgogi mit mariniertem Rindfleisch","excerpt":"Bulgogi selbst gemacht: dünne Rindfleischscheiben, mariniert in Sojasauce, Birne, Knoblauch und Sesam und mit Zwiebel angebraten. Mit Reis und Salat. Ergibt 4 Portionen.","summary":"Dieses Bulgogi besteht aus dünnen Rindfleischscheiben, die in Sojasauce, geriebener Birne, Knoblauch, Ingwer, braunem Zucker und Sesamöl mariniert werden. Sie werden bei starker Hitze mit Zwiebel und Frühlingszwiebel gebraten, bis sie goldbraun und glänzend sind, und mit weißem Reis und Salatblättern serviert.\n\nEs braucht 80 Minuten Vorbereitung, davon 60 Minuten Marinieren, und 15 Minuten Kochzeit. Ergibt 4 Portionen.","category":"Hauptgerichte","difficulty":"Einfach","course":"Hauptgericht","cuisine":"Koreanisch","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["Bulgogi","Bulgogi Rezept","koreanisches Rindfleisch mariniert","Bulgogi selber machen","Bulgogi Rindfleisch","koreanisches Bulgogi","Bulgogi mit Reis und Salat"],"ingredients":[{"name":"Rindfleisch (Lende oder Filet), in dünnen Scheiben","amount":"600","unit":"g","group":"Für das Fleisch und die Marinade"},{"name":"Sojasauce","amount":"4","unit":"Esslöffel","group":"Für das Fleisch und die Marinade"},{"name":"Birne","amount":"1/2","unit":"","group":"Für das Fleisch und die Marinade"},{"name":"Knoblauchzehen","amount":"4","unit":"","group":"Für das Fleisch und die Marinade"},{"name":"frischer Ingwer, gerieben","amount":"1","unit":"Teelöffel","group":"Für das Fleisch und die Marinade"},{"name":"brauner Zucker","amount":"2","unit":"Esslöffel","group":"Für das Fleisch und die Marinade"},{"name":"Sesamöl","amount":"1","unit":"Esslöffel","group":"Für das Fleisch und die Marinade"},{"name":"Sesamsamen","amount":"1","unit":"Esslöffel","group":"Für das Fleisch und die Marinade"},{"name":"Zwiebel","amount":"1","unit":"","group":"Zum Anbraten"},{"name":"Frühlingszwiebeln","amount":"3","unit":"","group":"Zum Anbraten"},{"name":"Pflanzenöl","amount":"1","unit":"Esslöffel","group":"Zum Anbraten"},{"name":"gekochter weißer Reis","amount":"600","unit":"g","group":"Zum Servieren"},{"name":"Salatblätter","amount":"8","unit":"","group":"Zum Servieren"}],"steps":[{"title":"Zutaten vorbereiten","content":"Bereiten Sie 600 g Rindfleisch (Lende oder Filet), 4 Esslöffel Sojasauce, ½ Birne, 4 Knoblauchzehen, Ingwer, 2 Esslöffel braunen Zucker, Sesamöl, Sesamsamen, 1 Zwiebel, 3 Frühlingszwiebeln, Pflanzenöl, gekochten Reis und Salat bereit.","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Zutaten vorbereiten"},{"title":"Fleisch schneiden","content":"Das Fleisch 30 Minuten einfrieren, damit es sich leichter schneiden lässt. Mit einem sehr scharfen Messer quer zur Faser in 2 bis 3 mm dünne Scheiben schneiden.","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Fleisch schneiden"},{"title":"Marinade anrühren","content":"In einer Schüssel 4 Esslöffel Sojasauce, ½ geriebene Birne, 4 gehackte Knoblauchzehen, 1 Teelöffel geriebenen Ingwer, 2 Esslöffel braunen Zucker, 1 Esslöffel Sesamöl und 1 Esslöffel Sesamsamen verrühren.","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Marinade anrühren"},{"title":"Fleisch mit der Marinade mischen","content":"Die Fleischscheiben in die Schüssel geben und mit den Händen mischen, bis alle gut bedeckt sind.","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Fleisch mit der Marinade mischen"},{"title":"Marinieren lassen","content":"Die Schüssel mit Frischhaltefolie abdecken und 1 bis 4 Stunden im Kühlschrank ziehen lassen. Nicht länger, sonst wird das Fleisch durch die Birne zu weich.","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Marinieren lassen"},{"title":"Zwiebel anbraten","content":"1 Esslöffel Öl in einer großen Pfanne bei starker Hitze erhitzen. 1 Zwiebel in Streifen und den weißen Teil von 3 Frühlingszwiebeln in Stücken zugeben und 2 Minuten anbraten, bis sie leicht Farbe nehmen.","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Zwiebel anbraten"},{"title":"Fleisch braten","content":"Das Fleisch mit der Marinade in zwei Portionen und ohne die Pfanne zu überfüllen zugeben und insgesamt 5 bis 6 Minuten bei starker Hitze braten, bis es goldbraun ist und die Sauce glänzt.","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Fleisch braten"},{"title":"Servieren","content":"Das Bulgogi auf 600 g gekochtem weißem Reis servieren, dazu Salatblätter zum Einwickeln des Fleisches. Das Grün der Frühlingszwiebeln in Ringen darüberstreuen.","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"Bulgogi mit mariniertem Rindfleisch: Servieren"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"Bulgogi mit mariniertem Rindfleisch"}],"notes":"Schneiden Sie das Fleisch so dünn wie möglich: So zieht es schnell durch und gart in wenigen Minuten. In Portionen und bei starker Hitze braten, damit es Farbe nimmt und nicht im eigenen Saft kocht. Am Tisch wickelt man etwas Fleisch und Reis in ein Salatblatt. Die Birne sorgt für Süße und macht das Fleisch zart; ersatzweise geht ein Apfel. Das Gericht ist durch die Sojasauce salzig, deshalb nicht nachsalzen. Es hält sich 3 Tage im Kühlschrank und lässt sich bis zu 2 Monate einfrieren.","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1 Portion (etwa 330 g mit Reis und Salat)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt: 600 g mageres Rindfleisch (Richtwert, ohne FDC-ID), 70 g Sojasauce, 100 g Birne, 12 g Knoblauch, 2 g Ingwer, 28 g brauner Zucker, 14 g Sesamöl, 9 g Sesamsamen, 150 g Zwiebel, 45 g Frühlingszwiebel (Richtwert, ohne FDC-ID), 14 g Öl, 600 g gekochter weißer Reis und 80 g Salat (Richtwert, ohne FDC-ID), alles gezählt.","note":"Schätzung pro Portion, einschließlich Reis und Salat. Der Natriumgehalt ist wegen der Sojasauce hoch; mit natriumarmer Sojasauce lässt er sich deutlich senken. Die Marinade wird vollständig gezählt, auch wenn ein Teil in der Schüssel bleibt."},"seo":{"title":"Bulgogi: koreanisches Rindfleisch mit Reis und Salat | Manual de Cocina","description":"Bulgogi selbst gemacht: dünnes Rindfleisch, mariniert in Sojasauce, Birne, Knoblauch und Sesam, mit Zwiebel gebraten. Mit Reis und Salat, 4 Portionen.","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"Welches Fleisch nimmt man für Bulgogi?","a":"Rinderlende oder Rinderfilet in sehr dünnen Scheiben. Auch Flanksteak oder Hüfte eignen sich, immer quer zur Faser geschnitten."},{"q":"Wie lange muss Bulgogi marinieren?","a":"Zwischen 1 und 4 Stunden im Kühlschrank. Kürzer gibt weniger Geschmack, länger als 4 Stunden macht das Fleisch durch die Birne zu weich."},{"q":"Was serviert man zu Bulgogi?","a":"Weißen Reis und Salatblätter zum Einwickeln des Fleisches. Dazu passen auch Kimchi oder Gurkenscheiben."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"7aceaf2f-db36-582c-bb9b-45f6a0e120ae","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"en","slug":"bulgogi-korean-marinated-beef","public_path":"/en/bulgogi-korean-marinated-beef","source_url":null,"title":"Bulgogi (Korean Marinated Beef)","excerpt":"Homemade bulgogi: thin slices of beef marinated in soy sauce, pear, garlic and sesame, then stir-fried with onion. Served with rice and lettuce. Serves 4.","summary":"This bulgogi uses thin slices of beef marinated in soy sauce, grated pear, garlic, ginger, brown sugar and sesame oil. They are stir-fried over high heat with onion and scallion until golden and glossy, and served with white rice and lettuce leaves.\n\nIt takes 80 minutes of prep, 60 of them marinating, and 15 of cooking. It serves 4.","category":"Main dishes","difficulty":"Easy","course":"Main course","cuisine":"Korean","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["bulgogi","bulgogi recipe","Korean marinated beef","how to make bulgogi","beef bulgogi","Korean beef bulgogi","bulgogi with rice and lettuce"],"ingredients":[{"name":"beef (sirloin or tenderloin), thinly sliced","amount":"600","unit":"g","group":"For the beef and marinade"},{"name":"soy sauce","amount":"4","unit":"tablespoon","group":"For the beef and marinade"},{"name":"pear","amount":"1/2","unit":"","group":"For the beef and marinade"},{"name":"garlic cloves","amount":"4","unit":"","group":"For the beef and marinade"},{"name":"fresh ginger, grated","amount":"1","unit":"teaspoon","group":"For the beef and marinade"},{"name":"brown sugar","amount":"2","unit":"tablespoon","group":"For the beef and marinade"},{"name":"sesame oil","amount":"1","unit":"tablespoon","group":"For the beef and marinade"},{"name":"sesame seeds","amount":"1","unit":"tablespoon","group":"For the beef and marinade"},{"name":"onion","amount":"1","unit":"","group":"For stir-frying"},{"name":"scallions","amount":"3","unit":"","group":"For stir-frying"},{"name":"vegetable oil","amount":"1","unit":"tablespoon","group":"For stir-frying"},{"name":"cooked white rice","amount":"600","unit":"g","group":"To serve"},{"name":"lettuce leaves","amount":"8","unit":"","group":"To serve"}],"steps":[{"title":"Prepare the ingredients","content":"Have ready 600 g beef (sirloin or tenderloin), 4 tablespoons soy sauce, ½ pear, 4 garlic cloves, ginger, 2 tablespoons brown sugar, sesame oil, sesame seeds, 1 onion, 3 scallions, vegetable oil, cooked rice and lettuce.","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"Bulgogi (Korean Marinated Beef): Prepare the ingredients"},{"title":"Slice the beef","content":"Freeze the beef for 30 minutes to make it easier to slice. With a very sharp knife, cut it against the grain into slices 2 to 3 mm thick.","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"Bulgogi (Korean Marinated Beef): Slice the beef"},{"title":"Make the marinade","content":"In a bowl, mix 4 tablespoons soy sauce, ½ grated pear, 4 minced garlic cloves, 1 teaspoon grated ginger, 2 tablespoons brown sugar, 1 tablespoon sesame oil and 1 tablespoon sesame seeds.","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"Bulgogi (Korean Marinated Beef): Make the marinade"},{"title":"Mix the beef with the marinade","content":"Add the beef slices to the bowl and mix with your hands until every piece is well coated.","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"Bulgogi (Korean Marinated Beef): Mix the beef with the marinade"},{"title":"Let it marinate","content":"Cover the bowl with plastic wrap and refrigerate for 1 to 4 hours. Do not go longer: the pear makes the beef too soft.","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"Bulgogi (Korean Marinated Beef): Let it marinate"},{"title":"Stir-fry the onion","content":"Heat 1 tablespoon of oil in a wide skillet over high heat. Add 1 onion cut into strips and the white part of 3 scallions in pieces and stir-fry for 2 minutes, until they start to brown.","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"Bulgogi (Korean Marinated Beef): Stir-fry the onion"},{"title":"Cook the beef","content":"Add the beef with its marinade in two batches, without crowding the pan, and stir-fry over high heat for 5 to 6 minutes in total, until golden and the sauce turns glossy.","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"Bulgogi (Korean Marinated Beef): Cook the beef"},{"title":"Serve","content":"Serve the bulgogi over 600 g cooked white rice, with lettuce leaves for wrapping the beef. Scatter the sliced green part of the scallions over the top.","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"Bulgogi (Korean Marinated Beef): Serve"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"Bulgogi (Korean Marinated Beef)"}],"notes":"Slice the beef as thin as you can: it marinates quickly and cooks in minutes. Cook it in batches over high heat so it browns instead of stewing in its juices. At the table, people usually wrap a little beef and rice in a lettuce leaf. The pear adds sweetness and tenderizes the beef; if you have none, use an apple. The dish is salty from the soy sauce, so do not add salt. It keeps for 3 days in the fridge and can be frozen for up to 2 months.","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1 serving (about 330 g with rice and lettuce)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings: 600 g lean beef (indicative value, with no FDC id), 70 g soy sauce, 100 g pear, 12 g garlic, 2 g ginger, 28 g brown sugar, 14 g sesame oil, 9 g sesame seeds, 150 g onion, 45 g scallion (indicative value, with no FDC id), 14 g oil, 600 g cooked white rice and 80 g lettuce (indicative value, with no FDC id), all counted.","note":"Estimate per serving, including the rice and lettuce. Sodium is high because of the soy sauce; low-sodium soy sauce can reduce it a lot. The marinade is counted in full, even if some stays in the bowl."},"seo":{"title":"Bulgogi (Korean Marinated Beef) with Rice and Lettuce | Manual de Cocina","description":"Homemade bulgogi: thin beef marinated in soy, pear, garlic and sesame, stir-fried with onion. With rice and lettuce, serves 4. Step by step with photos.","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"What cut of beef is used for bulgogi?","a":"Sirloin or tenderloin cut into very thin slices. Flank steak or round also work, always sliced against the grain."},{"q":"How long should bulgogi marinate?","a":"Between 1 and 4 hours in the fridge. Less gives less flavor, and more than 4 hours makes the beef too soft because of the pear."},{"q":"What do you serve with bulgogi?","a":"White rice and lettuce leaves for wrapping the beef. Kimchi or sliced cucumber go well too."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"823ae80b-2077-5cdb-8644-cab278f33d10","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"fr","slug":"bulgogi-boeuf-marine-coreen","public_path":"/fr/bulgogi-boeuf-marine-coreen","source_url":null,"title":"Bulgogi, bœuf mariné coréen","excerpt":"Bulgogi maison : fines tranches de bœuf marinées dans de la sauce soja, de la poire, de l'ail et du sésame, puis sautées avec de l'oignon. Servi avec du riz et de la laitue. Pour 4 portions.","summary":"Ce bulgogi se prépare avec de fines tranches de bœuf marinées dans de la sauce soja, de la poire râpée, de l'ail, du gingembre, du sucre roux et de l'huile de sésame. Elles sont sautées à feu vif avec de l'oignon et de la ciboule jusqu'à être dorées et brillantes, et servies avec du riz blanc et des feuilles de laitue.\n\nIl demande 80 minutes de préparation, dont 60 de marinade, et 15 de cuisson. Pour 4 portions.","category":"Plats principaux","difficulty":"Facile","course":"Plat principal","cuisine":"Coréenne","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["bulgogi","recette de bulgogi","bœuf mariné coréen","comment faire du bulgogi","bulgogi de bœuf","bœuf coréen mariné","bulgogi avec riz et laitue"],"ingredients":[{"name":"bœuf (faux-filet ou filet) en fines tranches","amount":"600","unit":"g","group":"Pour la viande et la marinade"},{"name":"sauce soja","amount":"4","unit":"cuillère à soupe","group":"Pour la viande et la marinade"},{"name":"poire","amount":"1/2","unit":"","group":"Pour la viande et la marinade"},{"name":"gousses d'ail","amount":"4","unit":"","group":"Pour la viande et la marinade"},{"name":"gingembre frais râpé","amount":"1","unit":"cuillère à café","group":"Pour la viande et la marinade"},{"name":"sucre roux","amount":"2","unit":"cuillère à soupe","group":"Pour la viande et la marinade"},{"name":"huile de sésame","amount":"1","unit":"cuillère à soupe","group":"Pour la viande et la marinade"},{"name":"graines de sésame","amount":"1","unit":"cuillère à soupe","group":"Pour la viande et la marinade"},{"name":"oignon","amount":"1","unit":"","group":"Pour sauter"},{"name":"ciboules","amount":"3","unit":"","group":"Pour sauter"},{"name":"huile végétale","amount":"1","unit":"cuillère à soupe","group":"Pour sauter"},{"name":"riz blanc cuit","amount":"600","unit":"g","group":"Pour servir"},{"name":"feuilles de laitue","amount":"8","unit":"","group":"Pour servir"}],"steps":[{"title":"Préparer les ingrédients","content":"Prévoir 600 g de bœuf (faux-filet ou filet), 4 cuillères à soupe de sauce soja, ½ poire, 4 gousses d'ail, du gingembre, 2 cuillères à soupe de sucre roux, de l'huile de sésame, des graines de sésame, 1 oignon, 3 ciboules, de l'huile végétale, du riz cuit et de la laitue.","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"Bulgogi, bœuf mariné coréen: Préparer les ingrédients"},{"title":"Couper la viande","content":"Mettre la viande 30 minutes au congélateur pour la trancher plus facilement. Avec un couteau bien aiguisé, la couper en tranches de 2 à 3 mm, dans le sens contraire des fibres.","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"Bulgogi, bœuf mariné coréen: Couper la viande"},{"title":"Préparer la marinade","content":"Dans un bol, mélanger 4 cuillères à soupe de sauce soja, ½ poire râpée, 4 gousses d'ail hachées, 1 cuillère à café de gingembre râpé, 2 cuillères à soupe de sucre roux, 1 cuillère à soupe d'huile de sésame et 1 cuillère à soupe de graines de sésame.","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"Bulgogi, bœuf mariné coréen: Préparer la marinade"},{"title":"Mélanger la viande à la marinade","content":"Ajouter les tranches de viande dans le bol et mélanger avec les mains jusqu'à ce qu'elles soient bien enrobées.","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"Bulgogi, bœuf mariné coréen: Mélanger la viande à la marinade"},{"title":"Laisser mariner","content":"Couvrir le bol de film alimentaire et le laisser de 1 à 4 heures au réfrigérateur. Pas plus longtemps : la poire attendrit trop la viande.","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"Bulgogi, bœuf mariné coréen: Laisser mariner"},{"title":"Faire sauter l'oignon","content":"Chauffer 1 cuillère à soupe d'huile dans une large poêle à feu vif. Ajouter 1 oignon coupé en lanières et le blanc de 3 ciboules en morceaux et faire sauter 2 minutes, jusqu'à ce qu'ils commencent à dorer.","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"Bulgogi, bœuf mariné coréen: Faire sauter l'oignon"},{"title":"Cuire la viande","content":"Ajouter la viande avec sa marinade en deux fois, sans surcharger la poêle, et faire sauter à feu vif 5 à 6 minutes au total, jusqu'à ce qu'elle soit dorée et que la sauce soit brillante.","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"Bulgogi, bœuf mariné coréen: Cuire la viande"},{"title":"Servir","content":"Servir le bulgogi sur 600 g de riz blanc cuit, avec des feuilles de laitue pour envelopper la viande. Parsemer du vert des ciboules en rondelles.","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"Bulgogi, bœuf mariné coréen: Servir"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"Bulgogi, bœuf mariné coréen"}],"notes":"Coupez la viande le plus finement possible : elle marine vite et cuit en quelques minutes. Faites-la cuire en plusieurs fois à feu vif pour qu'elle dore au lieu de bouillir dans son jus. À table, on enveloppe un peu de viande et de riz dans une feuille de laitue. La poire apporte de la douceur et attendrit la viande ; à défaut, utilisez une pomme. Le plat est salé par la sauce soja : ne salez pas. Il se conserve 3 jours au réfrigérateur et peut être congelé jusqu'à 2 mois.","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1 portion (environ 330 g avec riz et laitue)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions : 600 g de bœuf maigre (valeur indicative, sans identifiant FDC), 70 g de sauce soja, 100 g de poire, 12 g d'ail, 2 g de gingembre, 28 g de sucre roux, 14 g d'huile de sésame, 9 g de graines de sésame, 150 g d'oignon, 45 g de ciboule (valeur indicative, sans identifiant FDC), 14 g d'huile, 600 g de riz blanc cuit et 80 g de laitue (valeur indicative, sans identifiant FDC), le tout compté.","note":"Estimation par portion, riz et laitue compris. Le sodium est élevé à cause de la sauce soja ; avec une sauce soja pauvre en sodium, il peut baisser nettement. La marinade est comptée en entier, même si une partie reste dans le bol."},"seo":{"title":"Bulgogi, bœuf mariné coréen avec riz et laitue | Manual de Cocina","description":"Bulgogi maison : bœuf en fines tranches mariné au soja, à la poire, à l'ail et au sésame, sauté avec de l'oignon. Avec riz et laitue, 4 portions.","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"Quel morceau de bœuf utiliser pour le bulgogi ?","a":"Du faux-filet ou du filet coupé en tranches très fines. La bavette ou la rumsteck conviennent aussi, toujours tranchés dans le sens contraire des fibres."},{"q":"Combien de temps faut-il laisser mariner le bulgogi ?","a":"Entre 1 et 4 heures au réfrigérateur. Moins, il a moins de goût ; plus de 4 heures, la poire attendrit trop la viande."},{"q":"Avec quoi sert-on le bulgogi ?","a":"Avec du riz blanc et des feuilles de laitue pour envelopper la viande. Il va bien aussi avec du kimchi ou des rondelles de concombre."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"ee08cdc5-e40a-502f-8012-386382926c25","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"it","slug":"bulgogi-manzo-marinato-coreano","public_path":"/it/bulgogi-manzo-marinato-coreano","source_url":null,"title":"Bulgogi, manzo marinato coreano","excerpt":"Bulgogi fatto in casa: fettine sottili di manzo marinate in salsa di soia, pera, aglio e sesamo, poi saltate con la cipolla. Servito con riso e lattuga. Per 4 porzioni.","summary":"Questo bulgogi si prepara con fettine sottili di manzo marinate in salsa di soia, pera grattugiata, aglio, zenzero, zucchero di canna e olio di sesamo. Si saltano a fuoco vivo con cipolla e cipollotto fino a quando sono dorate e lucide, e si servono con riso bianco e foglie di lattuga.\n\nRichiede 80 minuti di preparazione, di cui 60 di marinatura, e 15 di cottura. Per 4 porzioni.","category":"Secondi piatti","difficulty":"Facile","course":"Secondo piatto","cuisine":"Coreana","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["bulgogi","ricetta bulgogi","manzo marinato coreano","come fare il bulgogi","bulgogi di manzo","carne coreana marinata","bulgogi con riso e lattuga"],"ingredients":[{"name":"manzo (controfiletto o filetto) a fettine sottili","amount":"600","unit":"g","group":"Per la carne e la marinata"},{"name":"salsa di soia","amount":"4","unit":"cucchiaio","group":"Per la carne e la marinata"},{"name":"pera","amount":"1/2","unit":"","group":"Per la carne e la marinata"},{"name":"spicchi d'aglio","amount":"4","unit":"","group":"Per la carne e la marinata"},{"name":"zenzero fresco grattugiato","amount":"1","unit":"cucchiaino","group":"Per la carne e la marinata"},{"name":"zucchero di canna","amount":"2","unit":"cucchiaio","group":"Per la carne e la marinata"},{"name":"olio di sesamo","amount":"1","unit":"cucchiaio","group":"Per la carne e la marinata"},{"name":"semi di sesamo","amount":"1","unit":"cucchiaio","group":"Per la carne e la marinata"},{"name":"cipolla","amount":"1","unit":"","group":"Per saltare"},{"name":"cipollotti","amount":"3","unit":"","group":"Per saltare"},{"name":"olio vegetale","amount":"1","unit":"cucchiaio","group":"Per saltare"},{"name":"riso bianco cotto","amount":"600","unit":"g","group":"Per servire"},{"name":"foglie di lattuga","amount":"8","unit":"","group":"Per servire"}],"steps":[{"title":"Prepara gli ingredienti","content":"Tieni pronti 600 g di manzo (controfiletto o filetto), 4 cucchiai di salsa di soia, ½ pera, 4 spicchi d'aglio, zenzero, 2 cucchiai di zucchero di canna, olio di sesamo, semi di sesamo, 1 cipolla, 3 cipollotti, olio vegetale, riso cotto e lattuga.","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"Bulgogi, manzo marinato coreano: Prepara gli ingredienti"},{"title":"Taglia la carne","content":"Metti la carne in freezer 30 minuti per tagliarla più facilmente. Con un coltello ben affilato, tagliala a fettine di 2-3 mm, contro la fibra.","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"Bulgogi, manzo marinato coreano: Taglia la carne"},{"title":"Prepara la marinata","content":"In una ciotola mescola 4 cucchiai di salsa di soia, ½ pera grattugiata, 4 spicchi d'aglio tritati, 1 cucchiaino di zenzero grattugiato, 2 cucchiai di zucchero di canna, 1 cucchiaio di olio di sesamo e 1 cucchiaio di semi di sesamo.","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"Bulgogi, manzo marinato coreano: Prepara la marinata"},{"title":"Mescola la carne con la marinata","content":"Aggiungi le fettine di carne nella ciotola e mescola con le mani finché sono ben ricoperte.","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"Bulgogi, manzo marinato coreano: Mescola la carne con la marinata"},{"title":"Lascia marinare","content":"Copri la ciotola con la pellicola trasparente e lasciala in frigorifero da 1 a 4 ore. Non di più: la pera ammorbidisce troppo la carne.","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"Bulgogi, manzo marinato coreano: Lascia marinare"},{"title":"Salta la cipolla","content":"Scalda 1 cucchiaio di olio in una padella larga a fuoco vivo. Aggiungi 1 cipolla a listarelle e la parte bianca di 3 cipollotti a pezzetti e salta 2 minuti, finché iniziano a dorarsi.","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"Bulgogi, manzo marinato coreano: Salta la cipolla"},{"title":"Cuoci la carne","content":"Aggiungi la carne con la sua marinata in due volte, senza affollare la padella, e salta a fuoco vivo per 5-6 minuti in tutto, finché è dorata e la salsa diventa lucida.","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"Bulgogi, manzo marinato coreano: Cuoci la carne"},{"title":"Servi","content":"Servi il bulgogi su 600 g di riso bianco cotto, con foglie di lattuga per avvolgere la carne. Cospargi con la parte verde dei cipollotti a rondelle.","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"Bulgogi, manzo marinato coreano: Servi"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"Bulgogi, manzo marinato coreano"}],"notes":"Taglia la carne il più sottile possibile: marina in fretta e cuoce in pochi minuti. Cuocila in più volte a fuoco vivo, così si rosola invece di bollire nel suo liquido. A tavola si avvolge un po' di carne e riso in una foglia di lattuga. La pera dà dolcezza e ammorbidisce la carne; se non l'hai, usa una mela. Il piatto è salato per la salsa di soia: non aggiungere sale. Si conserva 3 giorni in frigorifero e si può congelare fino a 2 mesi.","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1 porzione (circa 330 g con riso e lattuga)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni: 600 g di manzo magro (valore indicativo, senza id FDC), 70 g di salsa di soia, 100 g di pera, 12 g di aglio, 2 g di zenzero, 28 g di zucchero di canna, 14 g di olio di sesamo, 9 g di semi di sesamo, 150 g di cipolla, 45 g di cipollotto (valore indicativo, senza id FDC), 14 g di olio, 600 g di riso bianco cotto e 80 g di lattuga (valore indicativo, senza id FDC), tutto contato.","note":"Stima per porzione, compresi riso e lattuga. Il sodio è alto per la salsa di soia; con salsa di soia a basso contenuto di sodio si può ridurre molto. La marinata è contata per intero, anche se una parte resta nella ciotola."},"seo":{"title":"Bulgogi, manzo marinato coreano con riso e lattuga | Manual de Cocina","description":"Bulgogi fatto in casa: manzo a fettine sottili marinato con soia, pera, aglio e sesamo, saltato con cipolla. Con riso e lattuga, 4 porzioni.","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"Quale taglio di manzo si usa per il bulgogi?","a":"Controfiletto o filetto tagliato a fettine molto sottili. Vanno bene anche il scamone o la fesa, sempre tagliati contro la fibra."},{"q":"Quanto tempo deve marinare il bulgogi?","a":"Tra 1 e 4 ore in frigorifero. Meno tempo dà meno sapore, più di 4 ore rende la carne troppo morbida per via della pera."},{"q":"Con cosa si serve il bulgogi?","a":"Con riso bianco e foglie di lattuga per avvolgere la carne. Sta bene anche con kimchi o cetriolo a rondelle."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"80b29d02-7487-5eb7-93ba-08560efd85b9","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"ja","slug":"プルコギ","public_path":"/ja/プルコギ","source_url":null,"title":"プルコギ（韓国風牛肉の甘辛炒め）","excerpt":"薄切りの牛肉を、しょうゆ、梨、にんにく、ごまでつけ込み、玉ねぎと一緒に炒める手作りプルコギ。ごはんとレタスを添えて、4人分です。","summary":"このプルコギは、薄切りの牛肉を、しょうゆ、すりおろした梨、にんにく、しょうが、黒砂糖、ごま油につけ込みます。玉ねぎと長ねぎと一緒に強火で、こんがりつやが出るまで炒め、白いごはんとレタスを添えます。\n\n下ごしらえ80分（うちつけ込み60分）、加熱15分です。4人分です。","category":"主菜","difficulty":"簡単","course":"メイン料理","cuisine":"韓国料理","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["プルコギ","プルコギ レシピ","プルコギ 作り方","韓国料理 牛肉","牛肉 プルコギ","手作り プルコギ","プルコギ ごはん レタス"],"ingredients":[{"name":"牛肉（ももまたはヒレ）薄切り","amount":"600","unit":"g","group":"肉とつけだれ用"},{"name":"しょうゆ","amount":"4","unit":"大さじ","group":"肉とつけだれ用"},{"name":"梨","amount":"1/2","unit":"","group":"肉とつけだれ用"},{"name":"にんにく","amount":"4","unit":"","group":"肉とつけだれ用"},{"name":"しょうが（すりおろし）","amount":"1","unit":"小さじ","group":"肉とつけだれ用"},{"name":"黒砂糖","amount":"2","unit":"大さじ","group":"肉とつけだれ用"},{"name":"ごま油","amount":"1","unit":"大さじ","group":"肉とつけだれ用"},{"name":"いりごま","amount":"1","unit":"大さじ","group":"肉とつけだれ用"},{"name":"玉ねぎ","amount":"1","unit":"","group":"炒め用"},{"name":"長ねぎ（小ねぎ）","amount":"3","unit":"","group":"炒め用"},{"name":"サラダ油","amount":"1","unit":"大さじ","group":"炒め用"},{"name":"白いごはん（炊いたもの）","amount":"600","unit":"g","group":"盛りつけ用"},{"name":"レタスの葉","amount":"8","unit":"","group":"盛りつけ用"}],"steps":[{"title":"材料を準備する","content":"牛肉（ももまたはヒレ）600g、しょうゆ大さじ4、梨½個、にんにく4片、しょうが、黒砂糖大さじ2、ごま油、いりごま、玉ねぎ1個、小ねぎ3本、サラダ油、ごはん、レタスを用意します。","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: 材料を準備する"},{"title":"肉を切る","content":"切りやすくするため、肉を冷凍庫で30分冷やします。よく切れる包丁で、繊維を断つ向きに2〜3mmの薄切りにします。","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: 肉を切る"},{"title":"つけだれを作る","content":"ボウルに、しょうゆ大さじ4、すりおろした梨½個、みじん切りのにんにく4片、すりおろしたしょうが小さじ1、黒砂糖大さじ2、ごま油大さじ1、いりごま大さじ1を入れて混ぜます。","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: つけだれを作る"},{"title":"肉とたれを混ぜる","content":"ボウルに薄切りの肉を加え、全体にたれがよくなじむように手で混ぜます。","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: 肉とたれを混ぜる"},{"title":"つけ込む","content":"ボウルにラップをかけ、冷蔵庫で1〜4時間つけ込みます。梨で肉がやわらかくなりすぎるので、それ以上は置かないでください。","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: つけ込む"},{"title":"玉ねぎを炒める","content":"広めのフライパンにサラダ油大さじ1を入れて強火で熱します。くし形に切った玉ねぎ1個と、小ねぎ3本の白い部分をざく切りにして加え、焦げ目がつき始めるまで2分炒めます。","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: 玉ねぎを炒める"},{"title":"肉を焼く","content":"つけだれごと肉を2回に分けて加え、フライパンに詰めすぎないようにして、強火で合計5〜6分、こんがりしてたれにつやが出るまで炒めます。","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: 肉を焼く"},{"title":"盛りつける","content":"白いごはん600gの上にプルコギをのせ、肉を包むレタスの葉を添えます。小口切りにした小ねぎの青い部分を散らします。","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"プルコギ（韓国風牛肉の甘辛炒め）: 盛りつける"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"プルコギ（韓国風牛肉の甘辛炒め）"}],"notes":"肉はできるだけ薄く切ると、短時間でつけ込めて、数分で火が通ります。強火で数回に分けて焼くと、肉の水分で煮えずに、こんがり焼けます。食べるときは、レタスにごはんと肉を少しのせて包むのが定番です。梨は甘みを加えて肉をやわらかくします。なければ、りんごで代用できます。しょうゆの塩分があるので、塩は足さないでください。冷蔵庫で3日、冷凍で2か月保存できます。","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1人分（ごはんとレタスを含めて約330g）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。牛赤身肉600g（目安の値、FDC番号なし）、しょうゆ70g、梨100g、にんにく12g、しょうが2g、黒砂糖28g、ごま油14g、いりごま9g、玉ねぎ150g、小ねぎ45g（目安の値、FDC番号なし）、油14g、炊いた白米600g、レタス80g（目安の値、FDC番号なし）を使用しています。すべて全量を計算しています。","note":"ごはんとレタスを含む1人分の目安です。しょうゆのためナトリウムが多めで、減塩しょうゆを使うと大きく減らせます。つけだれは、一部がボウルに残っても全量で計算しています。"},"seo":{"title":"プルコギの作り方｜韓国風牛肉の甘辛炒め | Manual de Cocina","description":"しょうゆ、梨、にんにく、ごまでつけ込んだ薄切り牛肉を玉ねぎと炒める手作りプルコギ。ごはんとレタス付きで4人分。作り方を写真付きで解説します。","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"プルコギにはどの部位の牛肉を使いますか？","a":"ももやヒレを、ごく薄く切って使います。ばら肉やもも肉も使えますが、いずれも繊維を断つ向きに切ります。"},{"q":"プルコギは何時間つけ込みますか？","a":"冷蔵庫で1〜4時間です。それより短いと味が足りず、4時間を超えると、梨で肉がやわらかくなりすぎます。"},{"q":"プルコギには何を添えますか？","a":"白いごはんと、肉を包むレタスです。キムチや、薄切りのきゅうりもよく合います。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b850997b-f50a-5d4a-afd7-c139ba1bd18e","recipe_group_id":"5a537e08-8075-49e6-a9ae-34cc1ae44f80","language":"pt","slug":"bulgogi-carne-marinada-coreana","public_path":"/pt/bulgogi-carne-marinada-coreana","source_url":null,"title":"Bulgogi, carne bovina marinada coreana","excerpt":"Bulgogi caseiro: fatias finas de carne bovina marinadas em shoyu, pera, alho e gergelim, salteadas com cebola. Servido com arroz e alface. Rende 4 porções.","summary":"Este bulgogi leva fatias finas de carne bovina marinadas em shoyu, pera ralada, alho, gengibre, açúcar mascavo e óleo de gergelim. Elas são salteadas em fogo alto com cebola e cebolinha até ficarem douradas e brilhantes, e servidas com arroz branco e folhas de alface.\n\nLeva 80 minutos de preparo, 60 deles de marinada, e 15 de cozimento. Rende 4 porções.","category":"Pratos principais","difficulty":"Fácil","course":"Prato principal","cuisine":"Coreana","prep_time_minutes":80,"cook_time_minutes":15,"total_time_minutes":95,"servings":4,"keywords":["bulgogi","receita de bulgogi","carne marinada coreana","como fazer bulgogi","bulgogi de carne bovina","carne coreana marinada","bulgogi com arroz e alface"],"ingredients":[{"name":"carne bovina (contrafilé ou filé-mignon) em fatias finas","amount":"600","unit":"g","group":"Para a carne e a marinada"},{"name":"shoyu","amount":"4","unit":"colher de sopa","group":"Para a carne e a marinada"},{"name":"pera","amount":"1/2","unit":"","group":"Para a carne e a marinada"},{"name":"dentes de alho","amount":"4","unit":"","group":"Para a carne e a marinada"},{"name":"gengibre fresco ralado","amount":"1","unit":"colher de chá","group":"Para a carne e a marinada"},{"name":"açúcar mascavo","amount":"2","unit":"colher de sopa","group":"Para a carne e a marinada"},{"name":"óleo de gergelim","amount":"1","unit":"colher de sopa","group":"Para a carne e a marinada"},{"name":"sementes de gergelim","amount":"1","unit":"colher de sopa","group":"Para a carne e a marinada"},{"name":"cebola","amount":"1","unit":"","group":"Para saltear"},{"name":"cebolinhas","amount":"3","unit":"","group":"Para saltear"},{"name":"óleo vegetal","amount":"1","unit":"colher de sopa","group":"Para saltear"},{"name":"arroz branco cozido","amount":"600","unit":"g","group":"Para servir"},{"name":"folhas de alface","amount":"8","unit":"","group":"Para servir"}],"steps":[{"title":"Separe os ingredientes","content":"Tenha à mão 600 g de carne bovina (contrafilé ou filé-mignon), 4 colheres de sopa de shoyu, ½ pera, 4 dentes de alho, gengibre, 2 colheres de sopa de açúcar mascavo, óleo de gergelim, sementes de gergelim, 1 cebola, 3 cebolinhas, óleo vegetal, arroz cozido e alface.","image_url":"/recetas/bulgogi/paso-01.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Separe os ingredientes"},{"title":"Corte a carne","content":"Leve a carne ao freezer por 30 minutos para cortar com mais facilidade. Com uma faca bem afiada, corte em fatias de 2 a 3 mm, contra a fibra.","image_url":"/recetas/bulgogi/paso-02.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Corte a carne"},{"title":"Prepare a marinada","content":"Em uma tigela, misture 4 colheres de sopa de shoyu, ½ pera ralada, 4 dentes de alho picados, 1 colher de chá de gengibre ralado, 2 colheres de sopa de açúcar mascavo, 1 colher de sopa de óleo de gergelim e 1 colher de sopa de sementes de gergelim.","image_url":"/recetas/bulgogi/paso-03.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Prepare a marinada"},{"title":"Misture a carne com a marinada","content":"Junte as fatias de carne à tigela e misture com as mãos até todas ficarem bem cobertas.","image_url":"/recetas/bulgogi/paso-04.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Misture a carne com a marinada"},{"title":"Deixe marinar","content":"Cubra a tigela com filme plástico e deixe na geladeira de 1 a 4 horas. Não deixe por mais tempo: a pera amolece demais a carne.","image_url":"/recetas/bulgogi/paso-05.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Deixe marinar"},{"title":"Salteie a cebola","content":"Aqueça 1 colher de sopa de óleo em uma frigideira larga em fogo alto. Junte 1 cebola cortada em tiras e a parte branca de 3 cebolinhas em pedaços e salteie por 2 minutos, até começarem a dourar.","image_url":"/recetas/bulgogi/paso-06.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Salteie a cebola"},{"title":"Cozinhe a carne","content":"Acrescente a carne com a marinada em duas levas, sem amontoar, e salteie em fogo alto por 5 a 6 minutos no total, até dourar e o molho ficar brilhante.","image_url":"/recetas/bulgogi/paso-07.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Cozinhe a carne"},{"title":"Sirva","content":"Sirva o bulgogi sobre 600 g de arroz branco cozido, com folhas de alface para enrolar a carne. Espalhe por cima a parte verde das cebolinhas em rodelas.","image_url":"/recetas/bulgogi/paso-08.webp","image_alt":"Bulgogi, carne bovina marinada coreana: Sirva"}],"image_url":"/recetas/bulgogi/portada.webp","gallery":[{"url":"/recetas/bulgogi/portada.webp","alt":"Bulgogi, carne bovina marinada coreana"}],"notes":"Corte a carne o mais fino possível: ela marina rápido e cozinha em poucos minutos. Cozinhe em levas e em fogo alto para dourar em vez de ferver no próprio caldo. À mesa, costuma-se enrolar um pouco de carne e arroz em uma folha de alface. A pera dá doçura e amacia a carne; se não tiver, use maçã. O prato fica salgado por causa do shoyu, então não adicione sal. Dura 3 dias na geladeira e pode ser congelado por até 2 meses.","nutrition":{"calories":616,"protein_g":37.8,"carbs_g":60,"fat_g":24.2,"sodium_mg":1057,"serving_size":"1 porção (cerca de 330 g com arroz e alface)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções: 600 g de carne bovina magra (valor indicativo, sem código FDC), 70 g de shoyu, 100 g de pera, 12 g de alho, 2 g de gengibre, 28 g de açúcar mascavo, 14 g de óleo de gergelim, 9 g de sementes de gergelim, 150 g de cebola, 45 g de cebolinha (valor indicativo, sem código FDC), 14 g de óleo, 600 g de arroz branco cozido e 80 g de alface (valor indicativo, sem código FDC), tudo contado.","note":"Estimativa por porção, incluindo o arroz e a alface. O sódio é alto por causa do shoyu; com shoyu light ou com pouco sódio, pode cair bastante. A marinada é contada inteira, mesmo que parte fique na tigela."},"seo":{"title":"Bulgogi, carne bovina marinada coreana com arroz e alface | Manual de Cocina","description":"Bulgogi caseiro: carne em fatias finas marinada em shoyu, pera, alho e gergelim, salteada com cebola. Com arroz e alface, 4 porções. Passo a passo.","image_variants":["/recetas/bulgogi/portada-1x1.webp","/recetas/bulgogi/portada-4x3.webp","/recetas/bulgogi/portada-16x9.webp"],"faq":[{"q":"Qual corte de carne usar no bulgogi?","a":"Contrafilé ou filé-mignon cortado em fatias bem finas. Fraldinha ou coxão mole também servem, sempre cortados contra a fibra."},{"q":"Quanto tempo o bulgogi deve marinar?","a":"Entre 1 e 4 horas na geladeira. Menos tempo dá menos sabor, e mais de 4 horas deixa a carne mole demais por causa da pera."},{"q":"Com o que se serve o bulgogi?","a":"Com arroz branco e folhas de alface para enrolar a carne. Também combina com kimchi ou pepino em rodelas."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/bulgogi-carne-marinada-coreana') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
